            'type': 'choice',
            'instructions': (
                'Pick the single ' + kind + ' ID the user wants acted on. '
                'Ignore any ID mentioned only as another item, a different item, already handled, or needing nothing. '
                'If none fits, choose none.'
            ),
            'criteria': criteria,
        }
    }
    judgment = await kit.ask(state, questions)
    answer = judgment.get('target', {})
    choice = answer.get('choice', 'none')
    confidence = answer.get('confidence', 0.0)
    if choice == 'none' or choice not in ids or confidence < 0.5:
        return None
    return choice


