    end = len(text)
    ends = (' go to', ' to', '?', '.', ',', ';')
    for marker in ends:
        i = lower.find(marker, start)
        if i != -1 and i < end:
            end = i
    vendor = text[start:end].strip(" ,.?;:")
    return vendor


