            out.append(normalize(item))
        return out
    return value

def add_unique(items, value):
    for item in items:
        if item == value:
            return
    items.append(value)

def trailing_digits(text):
    digits = []
    started = False
    for ch in reversed(text):
        if ch.isdigit():
            digits.append(ch)
            started = True
        elif started:
            break
    digits.reverse()
    return "".join(digits)

def canonicalize(kind, text):
    if kind == "doc":
        prefix = DOCPREFIX
    else:
        prefix = INVPREFIX
    if text.startswith(prefix):
        return text
    digits = trailing_digits(text)
    if digits == "":
        return text
    return prefix + digits

