    if low.startswith("t-"):
        return text.replace(" ", "")
    digits = ""
    for ch in text:
        if "0" <= ch <= "9":
            digits += ch
    if digits != "":
        return digits
    return text.replace(" ", "")


def trip_variants(trip_id):
    text = str(trip_id).strip()
    out = []
    if text != "":
        out.append(text)
    norm = normalize_trip_id(text)
    if norm != "" and norm not in out:
        out.append(norm)
    if text.lower().startswith("t-"):
        digits = ""
        for ch in text:
            if "0" <= ch <= "9":
                digits += ch
        if digits != "" and digits not in out:
            out.append(digits)
    else:
        pref = "T-" + norm
        if pref not in out:
            out.append(pref)
    return out


async def decide(request, kit):
