    options[NONE_OPTION] = "the request is not for filing a claim, or no candidate clearly fits"

    judgment = await kit.ask(
        {"request": request, "candidates": candidates},
        {
            "filing_only": {
                "type": "noul",
                "instructions": "Is the request asking only to file one expense claim for one trip, with no other task, status question, cancellation, or policy question?"
            },
            "trip_id": {
                "type": "choice",
                "instructions": "Choose the trip mention the user wants filed now. Choose none if the request is not a filing request or if no candidate clearly fits.",
                "criteria": options
            }
        }
    )

    if not isinstance(judgment, dict):
        return {"handoff": "could not judge the filing request"}

    filing_only = readNumber(judgment.get("filing_only"))
    if filing_only is None or filing_only < FILING_THRESHOLD:
        return {"handoff": "the request is not clearly only a filing request"}

    trip_answer = judgment.get("trip_id")
    trip_choice, trip_confidence = extractChoice(trip_answer)

    if trip_choice is None:
        return {"handoff": "the request is not clearly asking to file one trip's expense claim"}
    if trip_choice == NONE_OPTION or trip_confidence < CONFIDENCE_THRESHOLD:
        return {"handoff": "the request is not clearly asking to file one trip's expense claim"}

    trip_id = normalizeTripId(trip_choice, kit)
    if trip_id == "":
        return {"handoff": "the selected trip id is not in a supported format"}

    trip = kit.read("read_trip", trip_id=trip_id)
    if not isinstance(trip, dict) or "error" in trip:
