                }
            }
        )
    except Exception:
        return {"handoff": "I couldn't determine whether this is a single claim filing."}

    if not isinstance(judgment, dict):
        return {"handoff": "I couldn't determine whether this is a single claim filing."}

    intent = judgment.get("intent")
    if not isinstance(intent, dict):
        return {"handoff": "I couldn't determine whether this is a single claim filing."}

    try:
        intentYes = float(intent.get("noul", 0.0))
    except Exception:
        return {"handoff": "I couldn't determine whether this is a single claim filing."}

    if intentYes <= 0.7:
        return {"handoff": "This request is not clearly a single expense-claim filing."}

    selected = tripTexts[0]

    if len(tripTexts) > 1:
