                        "criteria": criteria
                    }
                }
            )
        except Exception:
            return {"handoff": "I couldn't determine which trip to file."}

        if not isinstance(selection, dict):
            return {"handoff": "I couldn't determine which trip to file."}

        tripChoice = selection.get("trip")
        if not isinstance(tripChoice, dict):
            return {"handoff": "I couldn't determine which trip to file."}

        selected = tripChoice.get("choice")
        if selected == "none":
            return {"handoff": "I couldn't determine which trip to file."}

        if selected not in tripTexts:
            return {"handoff": "I couldn't determine which trip to file."}

        try:
            choiceConfidence = float(tripChoice.get("confidence", 0.0))
        except Exception:
            return {"handoff": "I couldn't determine which trip to file."}

        if choiceConfidence < MINCONFIDENCE:
            return {"handoff": "The trip selection is not clear enough to file."}

    try:
        tripInfo = kit.read("read_trip", trip_id=selected)
    except Exception:
        return {"handoff": "I couldn't verify that trip id."}

    if not verifytrip(tripInfo, selected):
        return {"handoff": "I couldn't verify that trip id."}

