async def decide(request, kit):
    text = request.lower()
    invs = kit.find("INV-[0-9]+", request)
    docs = kit.find("DOC-[0-9]+", request)

    def norm(v):
        if isinstance(v, float) and int(v) == v:
            return int(v)
        return v

    async def pick(cands, kind):
        if len(cands) == 1:
            return cands[0]
        criteria = {}
        for c in cands:
            criteria[c] = "act on " + c
        criteria["none"] = "none fit"
        ans = await kit.ask(
            {"request": request, "kind": kind, "candidates": cands},
            {
                "pick": {
                    "type": "choice",
                    "instructions": "Pick the one " + kind + " the user wants acted on. Ignore other mentioned ids that are explicitly said to need nothing.",
                    "criteria": criteria,
                }
            },
        )
        choice = ans["pick"]["choice"]
        if choice == "none":
            return ""
        return choice

    command_words = [
        "please",
        "can you",
        "could you",
        "hey",
        "when you have a moment",
        "when you get a moment",
    ]
    record_words = [
        "enter",
        "record",
    ]
    schedule_words = [
        "schedule",
        "set up payment",
        "set up the payment",
        "setup payment",
        "setup the payment",
    ]

    command = any(w in text for w in command_words)
    record_intent = command and any(w in text for w in record_words) and len(docs) > 0
    schedule_intent = command and any(w in text for w in schedule_words) and len(invs) > 0

    if record_intent and not schedule_intent:
        doc_id = await pick(docs, "document id")
        if doc_id == "":
            return {"handoff": "no document id is clearly identified"}
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or "error" in parsed:
            return {"handoff": "the document could not be parsed"}
        args = {}
        for key in [
            "invoice_number",
            "po_number",
            "invoice_date",
            "subtotal_usd",
            "freight_usd",
            "discount_percent",
            "discount_days",
            "net_days",
        ]:
            if key in parsed:
                args[key] = norm(parsed[key])
        return {
            "action": "record_invoice",
            "arguments": args,
            "reply": "Recorded " + doc_id + " in the ledger.",
        }

    if schedule_intent and not record_intent:
        invoice_id = await pick(invs, "invoice id")
        if invoice_id == "":
            return {"handoff": "no invoice id is clearly identified"}
        payable = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(payable, dict) or "error" in payable:
            return {"handoff": "the invoice amount could not be determined"}
        amount = norm(payable["amount_usd"])
        pay_on = payable["pay_on"]
        return {
            "action": "schedule_payment",
            "arguments": {
                "invoice_id": invoice_id,
                "amount_usd": amount,
                "pay_on": pay_on,
            },
            "reply": "Scheduled payment for " + invoice_id + ".",
        }

    return {"handoff": "request is out of scope for invoice entry or payment scheduling"}
