AFTER_BONUS = 1000

async def decide(request, kit):
    text = request.lower()

    def canon_doc(raw):
        low = raw.lower()
        if low.startswith("doc-"):
            return "DOC-" + raw.split("-")[-1]
        if low.startswith("document "):
            return "DOC-" + raw.split(" ")[-1].zfill(3)
        if low.startswith("doc "):
            return "DOC-" + raw.split(" ")[-1].zfill(3)
        return raw

    def canon_inv(raw):
        low = raw.lower()
        if low.startswith("inv-"):
            return "INV-" + raw.split("-")[-1]
        if low.startswith("invoice "):
            return "INV-" + raw.split(" ")[-1].zfill(3)
        if low.startswith("inv "):
            return "INV-" + raw.split(" ")[-1].zfill(3)
        return raw

    def all_positions(terms):
        positions = []
        for term in terms:
            start = 0
            while True:
                p = text.find(term, start)
                if p < 0:
                    break
                positions.append(p)
                start = p + 1
        return positions

    def raw_positions(raw):
        positions = []
        raw_low = raw.lower()
        start = 0
        while True:
            p = text.find(raw_low, start)
            if p < 0:
