        return choice

    doc_candidates = extract(DOC_PATTERNS, "doc")
    inv_candidates = extract(INV_PATTERNS, "invoice")

    question_style = ("?" in request) or text.startswith("has ") or text.startswith("have ") or text.startswith("had ") or text.startswith("is ") or text.startswith("are ") or text.startswith("was ") or text.startswith("were ") or text.startswith("did ")

