"""Reflective synthesis with conservative candidate selection."""

DRAFTPROMPT = """{{contract}}

Write a complete decision program for this job.

Prefer a safe hand-off over a wrong action.
If a request is ambiguous, incomplete, or could cause an external or irreversible side effect, do not guess; hand it off unless the judged runs clearly show the exact request should be served directly.
Do not over-generalize from one phrasing to another action.
Use code for everything code can decide. Use Jev only for judgments code cannot make.

Judged runs:
{{episodes}}

Reply with exactly one python block containing the full program."""

CAUTIOUSPROMPT = """{{contract}}

Write a complete decision program for this job.

This candidate should be extra conservative.
When in doubt, hand off rather than taking a side-effecting action.
Treat requests about scheduling, payments, booking, sending, deleting, changing state, or other external effects as hand-off unless the judged runs clearly justify direct handling.
Use code for deterministic checks; use Jev only for cases that code cannot decide.

Judged runs:
{{episodes}}

Reply with exactly one python block containing the full program."""

REPAIRPROMPT = """{{contract}}

This decision program was tried:

```python
{{program}}
```

These requests were wrong or were handed off when they could have been handled:

{{failures}}

Focus especially on any over-eager action that should have been handed off.
If an action was taken when the request was too ambiguous or incomplete, add an explicit guard so that action only fires when the request is unmistakable and fully specified.

Rewrite the whole program. Reply with exactly one python block."""

ROUNDS = 3
SHOWNFAILURES = 12


def getcode(reply):
    parts = reply.split("```")
    if len(parts) < 3:
        return reply.strip() + "\n"
    block = parts[1]
    if block.startswith("python"):
        block = block[len("python") :]
    return block.strip() + "\n"


def collectactions(failures):
    names = []
    for line in failures.split("\n"):
        if "took " in line and "should have been handed off" in line:
            start = line.find("took ") + len("took ")
            end = line.find(",", start)
            if end == -1:
                end = len(line)
            name = line[start:end].strip()
            if name and name not in names:
                names.append(name)
    return ", ".join(names)


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    draft = getcode(
        await lab.ask(
            lab.fill(DRAFTPROMPT, contract=lab.contract, episodes=shown)
        )
    )
    cautious = getcode(
        await lab.ask(
            lab.fill(CAUTIOUSPROMPT, contract=lab.contract, episodes=shown)
        )
    )

    taskids = list(lab.stream())
    best = draft
    bestscore = -10**9

    for program in (draft, cautious):
        score = 0.0
        for task_id in taskids:
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
        if score > bestscore:
            bestscore = score
            best = program

    program = best
    for roundno in range(ROUNDS):
        failures = []
        score = 0.0
        for task_id in taskids:
            reward, reason, observed = await lab.practice(program, task_id)
            score += reward
            if reward < 1:
                failures.append("Request: " + lab.request(task_id) + "\nOutcome: " + reason)

        lab.note("round " + str(roundno) + ": " + str(score))

        if score > bestscore:
            bestscore = score
            best = program

        if not failures:
            break

        focus = collectactions("\n".join(failures))
        failuretext = "\n\n".join(failures[:SHOWNFAILURES])
        if focus:
            failuretext = "Actions needing stricter gating: " + focus + "\n\n" + failuretext

        program = getcode(
            await lab.ask(
                lab.fill(
                    REPAIRPROMPT,
                    contract=lab.contract,
                    program=program,
                    failures=failuretext,
                )
            )
        )

    return best

