import re
from typing import Any, Iterable, Optional

# Conservative decision program:
# - Return "handoff" whenever there is any plausible external effect / state change.
# - Return "direct" only for clearly informational / analytical / drafting tasks.
# - Use Jev only when the deterministic rules cannot reasonably decide.

_EFF_PATTERNS = [
    # Scheduling / booking / coordination
    r"\b(schedule|reschedule|cancel|book|reserve|arrange|set up|coordinate)\b",
    r"\b(meeting|appointment|reservation|reservation|reservation|flight|hotel|table|event|calendar|interview|call)\b",

    # Sending / communicating on behalf of the user
    r"\b(send|forward|reply|respond|notify|contact|text|call|phone|message|email)\b",

    # Payments / money movement
    r"\b(pay|payment|refund|invoice|bill|charge|purchase|buy|order|transfer|withdraw|deposit|donate)\b",

    # State changes / edits / deletion / account changes
    r"\b(delete|remove|erase|purge|close|disable|enable|reset|change|update|edit|modify|create|add|set|move|publish|post|upload|download|install|uninstall|subscribe|unsubscribe|approve|reject|submit|apply)\b",

    # Explicit on-behalf language
    r"\bon my behalf\b",
    r"\bfor me\b",
]

# Clear informational / drafting / analysis intents that are safe to handle directly
# unless the request also includes effectful verbs or objects.
_SAFE_PATTERNS = [
    r"\b(explain|describe|summarize|summarise|analyze|analyse|compare|contrast|translate|define|debug|review|proofread|rewrite|draft|compose|write|brainstorm|generate|calculate|compute|extract|classify|sort|rank|list|outline|brainstorm)\b",
    r"\b(what is|what are|how do i|how to|why|when|where|who|which)\b",
]

_AMBIGUOUS_PATTERNS = [
    r"\bshould i\b",
    r"\bwould it be a good idea\b",
    r"\bcan you help me\b",
    r"\bi need help\b",
    r"\bnot sure\b",
    r"\bmaybe\b",
    r"\bpossibly\b",
]


def _iter_text(obj: Any) -> Iterable[str]:
    """Yield all textual content from common episode/context shapes."""
    if obj is None:
        return
    if isinstance(obj, str):
        yield obj
        return
    if isinstance(obj, bytes):
        try:
            yield obj.decode("utf-8", errors="ignore")
        except Exception:
            return
        return
    if isinstance(obj, dict):
        # Prefer user-like fields first if present.
        for key in ("messages", "message", "content", "text", "prompt", "utterance", "query", "input", "request"):
            if key in obj:
                yield from _iter_text(obj[key])
        # Fallback: any remaining string values.
        for v in obj.values():
            if isinstance(v, (str, bytes, dict, list, tuple)):
                yield from _iter_text(v)
        return
    if isinstance(obj, (list, tuple, set)):
        # If it looks like a chat transcript, prefer user messages.
        user_bits = []
        other_bits = []
        for item in obj:
            if isinstance(item, dict) and item.get("role") == "user":
                user_bits.append(item)
            else:
                other_bits.append(item)
        for item in user_bits + other_bits:
            yield from _iter_text(item)
        return


def _extract_request_text(context: Any) -> str:
    parts = []
    for t in _iter_text(context):
        s = " ".join(str(t).split())
        if s:
            parts.append(s)
    # If the context contains many fields, the last user-facing text is usually most relevant.
    # Keep a manageable concatenation while preserving order.
    return "\n".join(parts[-12:]).strip()


def _norm(text: str) -> str:
    return " " + re.sub(r"\s+", " ", text.lower()).strip() + " "


def _matches_any(text: str, patterns: Iterable[str]) -> bool:
    return any(re.search(p, text, flags=re.IGNORECASE | re.DOTALL) for p in patterns)


def _looks_effectful(text: str) -> bool:
    # Strongly effectful if explicit verbs appear.
    if _matches_any(text, _EFF_PATTERNS):
        return True

    # Additional conservative catches for common external/system actions.
    if re.search(r"\b(set up|set|create|make|change|update|edit|delete|remove)\b.*\b(account|calendar|event|meeting|appointment|booking|reservation|payment|payment method|order|invoice|subscription|email|message|post|profile|record|file|document)\b", text, flags=re.I | re.S):
        return True

    if re.search(r"\b(send|email|text|call|message|notify|forward|reply|respond)\b", text, flags=re.I):
        return True

    if re.search(r"\b(schedule|book|reserve|cancel|reschedule|arrange|coordinate)\b", text, flags=re.I):
        return True

    return False


def _looks_safe_direct(text: str) -> bool:
    # Clear info/drafting tasks with no obvious external action.
    safe = _matches_any(text, _SAFE_PATTERNS)
    if not safe:
        return False

    # If it also mentions external action, do not treat as safe.
    if _looks_effectful(text):
        return False

    return True


def _is_ambiguous(text: str) -> bool:
    return _matches_any(text, _AMBIGUOUS_PATTERNS)


def _consult_jev(text: str, reason: str) -> str:
    """
    Use Jev only when deterministic checks cannot decide.
    If no Jev callable is available, default to handoff.
    """
    prompt = (
        "Decide whether the request can be handled directly or should be handed off.\n"
        "Be extra conservative.\n"
        f"Reason for ambiguity: {reason}\n"
        f"Request:\n{text}\n"
        "Return exactly one word: direct or handoff."
    )
    for name in ("Jev", "jev", "JEV", "ask_jev"):
        fn = globals().get(name)
        if callable(fn):
            try:
                out = fn(prompt)
                if isinstance(out, dict) and "action" in out:
                    val = str(out["action"]).strip().lower()
                    return "handoff" if "hand" in val else "direct"
                if isinstance(out, str):
                    val = out.strip().lower()
                    if "hand" in val:
                        return "handoff"
                    if "direct" in val:
                        return "direct"
            except Exception:
                pass
    return "handoff"


def decide(context: Any) -> str:
    text = _extract_request_text(context)
    if not text:
        return "handoff"

    norm = _norm(text)

    # Deterministic checks first.
    if _looks_effectful(norm):
        return "handoff"

    if _looks_safe_direct(norm):
        return "direct"

    # If the request is clearly just informational or drafting, direct.
    # Otherwise, when in doubt, defer.
    if _is_ambiguous(norm):
        return _consult_jev(text, "ambiguous or mixed intent")

    # Default conservative stance.
    # If it's not clearly safe direct, hand off.
    return "direct" if _matches_any(norm, _SAFE_PATTERNS) else "handoff"


# Aliases for compatibility with different runners.
decision_program = decide
program = decide
run = decide
main = decide


if __name__ == "__main__":
    import sys

    raw = sys.stdin.read()
    print(decide(raw))
