def _normalize(request: Any) -> str:
    if request is None:
        return ""
    if isinstance(request, str):
        return request.strip()
    return str(request).strip()

def _is_fully_specified(text: str) -> bool:
    if not text:
        return False

    t = text.lower()

    # Explicit ambiguity / incompleteness guard.
