    if tail[0] in "\"'`":
        quote = tail[0]
        tail = tail[1:]
        name = tail.split(quote, 1)[0].strip()
    else:
        name = tail.split(",", 1)[0].split(".", 1)[0].split(";", 1)[0].split(":", 1)[0].strip()
        name = name.split(" ", 1)[0].strip()
    name = name.strip(".;:()[]{}")
