        return handoff("The request is not a supported AP action.")

    if job_choice == JOB_PAY:
        invoice_id, picked_confidence = await choose_id("invoice", invoice_ids)
        if invoice_id == "":
            return handoff("I could not identify a single invoice id to use.")

        amount = await kit.procedure("amount_payable", invoice_id=invoice_id)
        if not isinstance(amount, dict):
            return handoff("I could not determine the payable amount for " + invoice_id + ".")
        if "error" in amount:
            return handoff("I could not determine the payable amount for " + invoice_id + ".")

        amount_invoice = str(amount.get("invoice_id", invoice_id))
        amount_usd = amount.get("amount_usd")
