            if isinstance(value, str):
                out[key] = normalize_date_text(value)
            else:
                out[key] = value
        elif field_is_money(key):
            out[key] = normalize_money_value(value, has_formatted_money)
        else:
            out[key] = value
    return out


def kit_find_money_patterns(text):
    matches = []
    patterns = ('\\d+[.,]\\d{2}', '\\d+[.,]\\d{3}[.,]\\d{2}')
    for pattern in patterns:
        found = kit.find(pattern, text)
        for item in found:
            if item not in matches:
                matches.append(item)
    return matches


async def decide(request, kit):
    intent_answer = await kit.ask(
