    return "DOC-" + number


async def judgeJob(request, kit):
    criteria = {
        PAYMENT: "The request asks the desk to determine what is owed on a specific invoice and then schedule or set up payment for it.",
        RECORD: "The request asks the desk to enter or record a vendor invoice document into the ledger.",
        VENDOR: "The request is about a vendor or remittance/contact information.",
        OTHER: "The request is a status question, cancellation, dispute, edit, or anything not asking the desk to do one of the supported actions now."
    }

    first = await kit.ask(
        {"request": request},
        {
            "job": {
                "type": "choice",
                "instructions": "Decide what the request mainly asks the accounts payable desk to do right now.",
                "criteria": criteria
            }
        }
    )

    choice = first["job"]["choice"]
    confidence = first["job"]["confidence"]

    if choice == OTHER or confidence < MINJOB:
        second = await kit.ask(
            {
                "request": request,
                "first_choice": choice,
                "first_confidence": confidence
            },
            {
                "job": {
                    "type": "choice",
                    "instructions": "The first judgment was uncertain or may have been distracted by extra clauses. Re-evaluate the request using only the main AP action that should be handled now. Choose PAYMENT if the user wants the desk to work out what is owed on an invoice and schedule payment. Choose RECORD if the user wants the desk to enter a vendor invoice document into the ledger. Choose VENDOR only for vendor or remittance/contact questions. Choose OTHER for status, cancellation, dispute, edits, or anything not asking the desk to act now. Ignore any other invoices or documents that are explicitly described as needing no action.",
                    "criteria": criteria
                }
            }
        )
        choice = second["job"]["choice"]
        confidence = second["job"]["confidence"]

    return choice, confidence


async def chooseTarget(request, job, candidates, kit):
    if len(candidates) == 1:
        return candidates[0], 1.0

    criteria = {}
    for candidate in candidates:
        criteria[candidate] = "This is the identifier the request is asking to use."
    criteria[NONE] = "None of these fits."

    picked = await kit.ask(
        {"request": request, "job": job, "candidates": candidates},
        {
            "target": {
                "type": "choice",
                "instructions": "Choose which identifier the request means for the chosen job. If the request names a different item as needing nothing, ignore that one and pick the item the user actually wants handled. Pick none if nothing fits.",
                "criteria": criteria
            }
        }
    )

    return picked["target"]["choice"], picked["target"]["confidence"]


async def decide(request, kit):
    try:
        job, jobConfidence = await judgeJob(request, kit)

        if job == VENDOR or job == OTHER:
            return makeHandoff("This request is out of scope for payment scheduling or invoice recording.")

        candidates = unique(kit.find(DIGITPATTERN, request))
        if len(candidates) == 0:
            return makeHandoff("No invoice or document id could be identified.")

        selected, selectedConfidence = await chooseTarget(request, job, candidates, kit)

        if selected == NONE or selectedConfidence < MINTARGET:
            return makeHandoff("The target id is not clear enough to act on safely.")

        upper = selected.upper()
        if job == PAYMENT and "DOC" in upper:
            return makeHandoff("The chosen identifier looks like a document, not an invoice.")
        if job == RECORD and "INV" in upper:
            return makeHandoff("The chosen identifier looks like an invoice, not a document.")

        normalized = normalizeId(selected, job)
        if normalized == "":
            return makeHandoff("The target id could not be normalized.")

        if job == PAYMENT:
            amount = await kit.procedure("amount_payable", invoice_id=normalized)
            await kit.procedure(
                "schedule_payment",
                invoice_id=amount["invoice_id"],
                amount_usd=amount["amount_usd"],
                pay_on=amount["pay_on"]
            )
            return {
                "action": "schedule_payment",
                "arguments": {
                    "invoice_id": amount["invoice_id"],
                    "amount_usd": amount["amount_usd"],
                    "pay_on": amount["pay_on"]
                },
                "reply": "Payment scheduled for " + amount["invoice_id"] + "."
            }

        parsed = await kit.procedure("parse_invoice", doc_id=normalized)
        await kit.procedure("record_invoice", **parsed)
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Invoice recorded for " + normalized + "."
        }

    except Exception:
        return makeHandoff("I could not safely determine the requested AP action.")
