TRIP_PATTERN = "T-?\\d{3}|\\b\\d{3}\\b"
NONE = "none"
YES = 0.7
NO = 0.3

def unique(items):
    out = []
    seen = set()
    for item in items:
        if item not in seen:
            seen.add(item)
            out.append(item)
    return out

def normalize_trip_id(value):
    if value[:2] == "T-":
        return value
    if value[:1] == "T" and len(value) == 4 and value[1:].isdigit():
        return "T-" + value[1:]
    if len(value) == 3 and value.isdigit():
        return "T-" + value
    return value

def readtrip(kit, trip_id, raw):
    ids = [trip_id]
    if raw != trip_id:
        ids.append(raw)
    names = ["read_trip", "trip"]
    for name in names:
        for value in ids:
            try:
                data = kit.read(name, trip_id=value)
            except Exception:
                data = None
            if isinstance(data, dict) and "error" not in data:
                return data
    return None

async def decide(request, kit):
    found = kit.find(TRIP_PATTERN, request)
    candidates = unique(found)

    options = {}
    for trip_id in candidates:
        options[trip_id] = "the request refers to trip " + trip_id
    options[NONE] = "no trip claim is being requested"

