                    'type': 'choice',
                    'instructions': 'Choose the single document id the user wants entered into the ledger. Pick the likeliest option, or none if no candidate fits.',
                    'criteria': options
                }
            }
        )
        doc_id = judgment['doc_id']['choice']
        if doc_id == NONE_CHOICE:
            return {'handoff': 'The request mentions multiple possible document ids and none was chosen.'}

    parsed = await kit.procedure('parse_invoice', doc_id=doc_id)
    if isinstance(parsed, dict) and 'error' in parsed:
        return {'handoff': 'Could not parse document ' + doc_id + ': ' + str(parsed['error'])}

    record = normalizeRecord(parsed)
    result = await kit.procedure('record_invoice', **record)
    if isinstance(result, dict) and 'error' in result:
        return {'handoff': 'Could not record document ' + doc_id + ': ' + str(result['error'])}

    ledger_id = ''
    if isinstance(result, dict) and 'ledger_id' in result:
        ledger_id = str(result['ledger_id'])

    reply = 'Recorded ' + doc_id + ' in the ledger.'
    if ledger_id != '':
        reply = reply + ' Ledger id: ' + ledger_id + '.'
    return {'action': 'record_invoice', 'arguments': record, 'reply': reply}
