PATTERN_DOC = "[Dd][Oo][Cc][- ]?[0-9]{3}"
PATTERN_NUM = "\\b[0-9]{3}\\b"
HANDOFF_NO_ID = "No document id was found for the vendor invoice."
HANDOFF_AMBIG = "Multiple document ids were mentioned and the target is ambiguous."
HANDOFF_BAD = "The invoice document could not be recorded because its parsed invoice date is not in YYYY-MM-DD format."
REPLY_OK = "Recorded the invoice document in the ledger."

async def decide(request, kit):
    def normalize(match):
        digits = ""
        for ch in match:
            if ch >= "0" and ch <= "9":
                digits = digits + ch
        if len(digits) == 3:
            return "DOC-" + digits
        return ""

    found = []
    patterns = [PATTERN_DOC, PATTERN_NUM]
    for pattern in patterns:
        try:
            matches = kit.find(pattern, request)
        except Exception:
            matches = []
        for match in matches:
            doc_id = normalize(match)
            if doc_id and doc_id not in found:
                found.append(doc_id)

    if len(found) == 0:
        return {"handoff": HANDOFF_NO_ID}

    doc_id = found[0]
    if len(found) > 1:
        questions = {
            "doc": {
                "type": "choice",
                "instructions": "Choose the single document id the user means to enter into the ledger. Choose none if no document id should be entered.",
                "criteria": {}
            }
        }
        for doc in found:
            questions["doc"]["criteria"][doc] = "the target document id"
        questions["doc"]["criteria"]["none"] = "no suitable document id"
        answer = await kit.ask({"request": request, "candidates": found}, questions)
        choice = answer["doc"]["choice"]
        if choice == "none" or choice not in found:
            return {"handoff": HANDOFF_AMBIG}
        doc_id = choice

    try:
        record = await kit.procedure("parse_invoice", doc_id=doc_id)
    except Exception:
        return {"handoff": "The invoice document could not be parsed."}

    if not isinstance(record, dict):
        return {"handoff": "The invoice document could not be parsed."}

    date_text = record.get("invoice_date", "")
    if not isinstance(date_text, str) or len(date_text) != 10:
        return {"handoff": HANDOFF_BAD}
    if date_text[4] != "-" or date_text[7] != "-":
        return {"handoff": HANDOFF_BAD}
    for i in range(10):
        ch = date_text[i]
        if i == 4 or i == 7:
            continue
        if ch < "0" or ch > "9":
            return {"handoff": HANDOFF_BAD}

    return {
        "action": "record_invoice",
        "arguments": record,
        "reply": REPLY_OK
    }
