PATTERNS = ["doc-[0-9]+", "doc [0-9]+", "document [0-9]+"]
NO_DOC = "No vendor invoice document id was found in the request."
MANY_DOCS = "The request mentions more than one document id."
NO_CHOICE = "No single document id could be determined."

async def decide(request, kit) -> dict:
    text = request.lower()
    found = []
    for pattern in PATTERNS:
        matches = kit.find(pattern, text)
        for match in matches:
            digits = ""
            for ch in match:
                if ch >= "0" and ch <= "9":
                    digits += ch
            if digits != "":
                doc_id = "DOC-" + digits
                if doc_id not in found:
                    found.append(doc_id)

    if len(found) == 0:
        return {"handoff": NO_DOC}

    if len(found) > 1:
        options = {}
        for doc_id in found:
            options[doc_id] = "record this document"
        options["none"] = "no document fits"
        answer = await kit.ask(
            {"request": request, "doc_ids": found},
            {
                "target_doc": {
                    "type": "choice",
                    "instructions": "The request names several document ids. Which one should be recorded as the vendor invoice? Pick the likeliest target document id, or none if no document should be recorded.",
                    "criteria": options,
                }
            },
        )
        choice = answer["target_doc"]["choice"]
        if choice == "none":
            return {"handoff": NO_CHOICE}
        doc_id = choice
    else:
        doc_id = found[0]

    record = await kit.procedure("parse_invoice", doc_id=doc_id)
    return {
        "action": "record_invoice",
        "arguments": record,
        "reply": "Recorded " + doc_id + " in the ledger.",
    }
