async def decide(request, kit):
    text = request.lower()

    def build_id(match, prefix):
        if "-" in match:
            return match.upper()
        digits = ""
        for ch in match:
            if ch >= "0" and ch <= "9":
                digits = digits + ch
        return prefix.upper() + "-" + digits

    def collect_ids(prefix, label, source):
        found = []
        patterns = [prefix + "-[0-9]+", label + "[ ]*[0-9]+"]
        for pat in patterns:
            matches = kit.find(pat, source)
            for match in matches:
                item = build_id(match, prefix)
                if item not in found:
                    found.append(item)
        return found

    def fix_date(value):
        if isinstance(value, str) and len(value) == 10 and value[2] == "." and value[5] == ".":
            return value[6:10] + "-" + value[3:5] + "-" + value[0:2]
        return value

    def choose_one(kind, ids):
        if len(ids) == 1:
            return ids[0]
        state = {"request": request, "kind": kind, "ids": ids}
        questions = {
            "target": {
                "type": "choice",
                "instructions": "Pick the single " + kind + " id the user means, or none if none fits.",
                "criteria": dict([(item, item) for item in ids + ["none"]]),
            }
        }
        answer = await kit.ask(state, questions)
        target = answer["target"]["choice"]
        if target == "none":
            return None
        return target

    record_words = ["record", "enter"]
    schedule_words = ["schedule", "set up", "set-up", "work out what we owe", "work out what we owe on", "set up payment", "set up the payment"]

    record = any(word in text for word in record_words)
    schedule = any(word in text for word in schedule_words)

    doc_ids = collect_ids("doc", "document", text)
    inv_ids = collect_ids("inv", "invoice", text)

    if record and schedule and len(doc_ids) > 0 and len(inv_ids) > 0:
        return {"handoff": "The request appears to contain both a payment-scheduling task and a ledger-entry task.", "read_only": True}

    if record:
        target = await choose_one("document", doc_ids)
        if target is None:
            return {"handoff": "I could not identify which document to record.", "read_only": True}
        parsed = await kit.procedure("parse_invoice", doc_id=target)
        args = dict(parsed)
        args["doc_id"] = target
        if "invoice_date" in args:
            args["invoice_date"] = fix_date(args["invoice_date"])
        return {
            "action": "record_invoice",
            "arguments": args,
            "reply": "Recorded " + target + ".",
        }

    if schedule:
        target = await choose_one("invoice", inv_ids)
        if target is None:
            return {"handoff": "I could not identify which invoice to schedule.", "read_only": True}
        payable = await kit.procedure("amount_payable", invoice_id=target)
        return {
            "action": "schedule_payment",
            "arguments": payable,
            "reply": "Scheduled payment for " + target + ".",
        }

    return {"handoff": "This request is outside payment scheduling and invoice entry.", "read_only": True}
