def memory_text(memory):
    return (memory["name"] + " " + memory["description"]).lower()


def find_name(memories, any_words=(), all_words=(), read_only=None):
    for memory in memories:
        if read_only is not None and bool(memory.get("read_only")) != read_only:
            continue
        text = memory_text(memory)
        good = True
        for word in all_words:
            if word not in text:
                good = False
                break
        if not good:
            continue
        if any_words:
            hit = False
            for word in any_words:
                if word in text:
                    hit = True
                    break
            if not hit:
                continue
        return memory["name"]
    return ""


async def learn(lab):
    memories = list(lab.memories)

    if len(memories) == 0:
        shown = "\n\n".join(lab.render(e) for e in lab.episodes)
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
        for kind in lab.parse(reply):
            lab.remember(kind["name"], kind["description"], kind["guidance"], route="none", read_only=not kind["acts"])
        memories = list(lab.memories)
    else:
        for memory in memories:
            lab.remember(**memory)

    out_of_scope_name = find_name(
        memories,
        any_words=("out_of_scope", "status", "change", "hold", "cancel", "dispute", "delete", "remove", "reminder", "remind"),
