        }

    if action == "record":
        doc_ids = kit.find(DOC_PATTERN, request)
        if len(doc_ids) == 0:
            return handoff("I need a specific document id in the form DOC-### to enter the vendor invoice.", False)
        if has_phrase(text, NEGATION_PHRASES) and len(doc_ids) == 1:
            return handoff("The request is negated or says not to record that document.", True)
        doc_id = await select_candidate("document id", doc_ids)
        if doc_id == "":
            return handoff("I couldn't identify which document to record.", False)
        parsed = await kit.procedure("parse_invoice", doc_id=doc_id)
        if not isinstance(parsed, dict) or "error" in parsed:
            return handoff("I couldn't parse " + doc_id + ", so I can't record it.", False)
        return {
            "action": "record_invoice",
            "arguments": parsed,
            "reply": "Recorded " + doc_id + " in the ledger.",
        }

    return handoff("This request is outside the supported payment-scheduling and invoice-entry actions.", True)
