def clean_source(text):
    text = text.strip()
    fence = "```"
    if text.startswith(fence):
        parts = text.split(fence)
        if len(parts) >= 3:
            text = parts[1]
            if text.startswith("python"):
                text = text[6:]
    return text.strip()


def score_kind(kind):
    text = (kind["name"] + " " + kind["description"]).lower()
    words = ["enter", "record", "ledger", "document", "invoice"]
    score = 0
    for word in words:
        if word in text:
            score += 1
    return score


def choose_target_kind(kinds):
    best = None
    best_score = -1
    for kind in kinds:
        if not kind["acts"]:
            continue
        score = score_kind(kind)
        if score > best_score:
            best = kind
            best_score = score
    if best is not None:
        return best
    for kind in kinds:
        if kind["acts"]:
            return kind
    return None


async def learn(lab):
    rendered = "\n\n".join(lab.render(episode) for episode in lab.episodes)

    if len(lab.memories) == 0:
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=rendered))
        kinds = lab.parse(reply)
        if not isinstance(kinds, list):
            return ROUTER

        target_kind = choose_target_kind(kinds)
        target_name = target_kind["name"] if target_kind is not None else None

        for kind in kinds:
            if kind["name"] == target_name:
                continue
            lab.remember(
                kind["name"],
                kind["description"],
                kind["guidance"],
                route="none",
                read_only=not kind["acts"],
            )

        if target_kind is not None:
            program = await lab.ask(
                lab.fill(
                    PROGRAM_PROMPT,
                    contract=lab.contract,
                    current=target_kind["guidance"],
                    episodes=rendered,
                )
            )
            lab.remember(
                target_kind["name"],
                target_kind["description"],
                clean_source(program),
                route="program",
                read_only=False,
            )

        return ROUTER

    target_memory = None
    for memory in lab.memories:
        lab.remember(
            memory["name"],
            memory["description"],
            memory["body"],
            route=memory["route"],
            read_only=memory["read_only"],
        )
        if target_memory is None and score_kind(memory) >= 3 and memory["route"] == "program":
            target_memory = memory

    if target_memory is None:
        for memory in lab.memories:
            if memory["name"] == "vendor_invoice_entry":
                target_memory = memory
                break

    if target_memory is not None:
        program = await lab.ask(
            lab.fill(
                PROGRAM_PROMPT,
                contract=lab.contract,
                current=target_memory["body"],
                episodes=rendered,
            )
        )
        lab.remember(
            target_memory["name"],
            target_memory["description"],
            clean_source(program),
            route="program",
            read_only=False,
        )

    return ROUTER

