)
EXPLICIT_PATTERN = "INV-[0-9]{1,3}"
BARE_PATTERN = "\\b[0-9]{1,3}\\b"

def normalizeId(token):
    if token.startswith("INV-"):
        token = token[4:]
    try:
        value = int(token)
    except Exception:
        return None
    return "INV-" + ("000" + str(value))[-3:]

async def decide(request, kit):
    text = request.lower()

    action = any(marker in text for marker in ACT_MARKERS)
    blocked = any(marker in text for marker in NO_ACTION_MARKERS)

    if blocked and not action:
        return {"handoff": "request is not a payment-scheduling action", "read_only": True}

    if not action:
        return {"handoff": "request does not plainly ask to schedule payment now", "read_only": True}

    ids = kit.find(EXPLICIT_PATTERN, request)
    if len(ids) == 0:
        ids = kit.find(BARE_PATTERN, request)

    candidates = []
    seen = set()
    for token in ids:
        nid = normalizeId(token)
        if nid is not None and nid not in seen:
            seen.add(nid)
            candidates.append(nid)

    if len(candidates) == 0:
        return {"handoff": "could not identify an invoice id"}

    invoiceId = candidates[0]
    if len(candidates) > 1:
        criteria = {"none": "no invoice fits"}
        for cand in candidates:
            criteria[cand] = "schedule this invoice"
        state = {"request": request, "candidates": candidates}
        questions = {
