async def decide(request, kit):
    ACTIONWORDS = ['schedule', 'set up']
    BLOCKWORDS = [
        'hold the payment',
        'hold payment',
        'delay the payment',
        'delay payment',
        'cancel',
        'change',
        'reject',
        'reverse',
        'status',
        'dispute',
        'do not schedule',
        "don't schedule",
        'do not set up',
        "don't set up",
        'not to act'
    ]

    def makeid(text):
        digits = ''.join([ch for ch in text if ch >= '0' and ch <= '9'])
        if len(digits) == 0:
            return ''
        return 'INV-' + digits.zfill(3)

    def wantaction(text):
        low = text.lower()
        hasaction = False
        for word in ACTIONWORDS:
            if word in low:
                hasaction = True
                break
        if not hasaction:
            return False
        for word in BLOCKWORDS:
            if word in low:
                return False
        return True

    low = request.lower()

    if not wantaction(request):
        return {
            'handoff': 'this request is not a payment-scheduling request right now',
            'read_only': True
        }

    found = kit.find('inv-\\d+|(?<!inv-)\\b\\d{1,3}\\b', low)
    candidates = []
    seen = set()
    for raw in found:
        invoice_id = makeid(raw)
        if invoice_id != '' and invoice_id not in seen:
            seen.add(invoice_id)
            candidates.append(invoice_id)

    if len(candidates) == 0:
        return {
            'handoff': 'could not identify an invoice id to schedule'
        }

    invoice_id = candidates[0]
    if len(candidates) > 1:
        state = {
            'request': request,
            'candidates': candidates
        }
        questions = {
            'pick': {
                'type': 'choice',
                'instructions': 'Choose the single invoice id in `candidates` that should be scheduled now. Ignore any ids the request says need nothing or mentions only as a different one. Choose `none` if no invoice should be acted on.',
                'criteria': dict([(cid, cid) for cid in candidates] + [('none', 'none')])
            }
        }
        answer = await kit.ask(state, questions)
        pick = answer.get('pick', {})
        choice = pick.get('choice', 'none')
        if choice == 'none' or choice not in seen:
            return {
                'handoff': 'could not identify a single invoice to schedule'
            }
        invoice_id = choice

    try:
        payable = await kit.procedure('amount_payable', invoice_id=invoice_id)
    except Exception:
        return {
            'handoff': 'could not determine the payable amount for ' + invoice_id
        }

    if not isinstance(payable, dict):
        return {
            'handoff': 'could not determine the payable amount for ' + invoice_id
        }
    if 'error' in payable:
        return {
            'handoff': 'could not determine the payable amount for ' + invoice_id
        }
    if 'amount_usd' not in payable or 'pay_on' not in payable:
        return {
            'handoff': 'could not determine the payable amount for ' + invoice_id
        }

    amount_usd = payable['amount_usd']
    pay_on = payable['pay_on']

    return {
        'action': 'schedule_payment',
        'arguments': {
            'invoice_id': invoice_id,
            'amount_usd': amount_usd,
            'pay_on': pay_on
        },
        'reply': 'Scheduled payment for ' + invoice_id + '.'
    }
