async def decide(request, kit):
    def normalize(text):
        text = str(text).upper()
        if text.startswith("INV-"):
            return text
        digits = kit.find("[0-9]+", text)
        if len(digits) > 0:
            num = str(digits[0])
            if len(num) < 3:
                num = ("000" + num)[-3:]
            return "INV-" + num
        return text

    def unique(items):
        seen = set()
        out = []
        for item in items:
            if item not in seen:
                seen.add(item)
                out.append(item)
        return out

    matches = []
    patterns = ["[Ii][Nn][Vv]-[0-9]+", "[Ii]nvoice[ ]*[0-9]+"]
    for pat in patterns:
        try:
            found = kit.find(pat, request)
        except Exception:
            found = []
        for item in found:
            norm = normalize(item)
            if norm not in matches:
                matches.append(norm)
    matches = unique(matches)

    intent_options = {
        "schedule": "request asks to schedule payment for one invoice already in the ledger",
        "read_only": "request only asks for amount due, status, or other answer-only invoice information",
