{"source":"ACTION_SCHEDULE = 'schedule'
ACTION_RECORD = 'record'
ACTION_NONE = 'none'
HANDOFF_ROUTE = 'low'
MEMORY = 'Invoice ids in tools are written as INV-###, not a bare number. For payment scheduling, call amount_payable(invoice_id) first and then return schedule_payment with the same invoice_id, amount_usd, and pay_on. For ledger entry, call parse_invoice(doc_id) first and then return record_invoice with the parsed record.'

async def decide(request, kit):
    def unique(values):
        seen = set()
        out = []
        for value in values:
            if value not in seen:
                seen.add(value)
                out.append(value)
        return out

    def handoff(reason):
        return {'handoff': reason, 'read_only': True, 'route': HANDOFF_ROUTE, 'memory': MEMORY}

    def candidate_ids(prefix):
        raw = kit.find(prefix + r'\d{1,3}', request)
        bare = kit.find(r'(?<![A-Z-])\b\d{3}\b', request)
        return unique(raw + bare)

    def criteria_for(values):
        criteria = {}
        for value in values:
            criteria[value] = 'the id to act on'
        criteria[ACTION_NONE] = 'none of these'
        return criteria

    async def ask_choice(name, criteria, instructions, state):
        try:
            reply = await kit.ask(state, {name: {'type': 'choice', 'instructions': instructions, 'criteria': criteria}})
            return reply[name]['choice']
        except Exception:
            return ACTION_NONE

    action = await ask_choice(
        'action',
        {
            ACTION_SCHEDULE: 'schedule payment for an invoice already in the ledger',
            ACTION_RECORD: 'enter a vendor invoice document into the ledger',
            ACTION_NONE: 'anything else or unclear'
        },
        'Decide whether the request plainly asks to schedule payment for an entered invoice, enter a vendor invoice document into the ledger, or neither. Choose none for status questions, cancellations, disputes, vendor questions, or anything outside these jobs.',
        {'request': request}
    )

    if action == ACTION_NONE:
        return handoff('outside the desk jobs')

    if action == ACTION_SCHEDULE:
        ids = candidate_ids('INV-')
        if not ids:
            return handoff('invoice id not found')
        chosen = await ask_choice(
            'invoice_id',
            criteria_for(ids),
            'Select the invoice id the request should act on. Choose none if none of the candidates is the one to schedule or if the request is not clearly asking for payment scheduling.',
            {'request': request, 'candidates': ids}
        )
        if chosen == ACTION_NONE or chosen not in ids:
            return handoff('invoice id not found')
        try:
            result = await kit.procedure('amount_payable', invoice_id=chosen)
        except Exception as err:
            result = {'error': str(err)}
        if not isinstance(result, dict) or 'error' in result:
            try:
                kit.read('read_invoice', invoice_id=chosen)
            except Exception:
                pass
            return handoff('amount_payable failed for ' + chosen)
        invoice_id = result.get('invoice_id', chosen)
        amount_usd = result.get('amount_usd')
        pay_on = result.get('pay_on')
        if amount_usd is None or pay_on is None:
            return handoff('amount_payable returned incomplete data for ' + chosen)
        return {'action': 'schedule_payment', 'arguments': {'invoice_id': invoice_id, 'amount_usd': amount_usd, 'pay_on': pay_on}, 'reply': 'Scheduled payment for ' + str(invoice_id) + '.'}

    if action == ACTION_RECORD:
        ids = candidate_ids('DOC-')
        if not ids:
            return handoff('document id not found')
        chosen = await ask_choice(
            'doc_id',
            criteria_for(ids),
            'Select the document id the request should act on. Choose none if none of the candidates is the one to enter or if the request is not clearly asking to enter a vendor invoice document.',
            {'request': request, 'candidates': ids}
        )
        if chosen == ACTION_NONE or chosen not in ids:
            return handoff('document id not found')
        try:
            result = await kit.procedure('parse_invoice', doc_id=chosen)
        except Exception as err:
            result = {'error': str(err)}
        if not isinstance(result, dict) or 'error' in result:
            try:
                kit.read('read_document', doc_id=chosen)
            except Exception:
                pass
            return handoff('parse_invoice failed for ' + chosen)
        return {'action': 'record_invoice', 'arguments': result, 'reply': 'Recorded ' + str(result.get('doc_id', chosen)) + '.'}

    return handoff('outside the desk jobs')"}

{"source":"ACTIONS = ('schedule_payment', 'record_invoice', 'other')
NONE = 'none'
INV_PREFIX = 'INV'
DOC_PREFIX = 'DOC'
INV_PATTERN = 'INV-[0-9]+'
DOC_PATTERN = 'DOC-[0-9]+'
NUM_PATTERN = r'\b[0-9]{1,3}\b'

async def decide(request, kit):
    action_question = {
        'type': 'choice',
        'instructions': 'Decide whether this request is a direct request to schedule payment for an invoice already in the ledger, a direct request to enter a vendor invoice document into the ledger, or neither. Choose the best option for the whole request.',
        'criteria': {
            'schedule_payment': 'The request asks to schedule payment of an invoice already in the ledger.',
            'record_invoice': 'The request asks to enter a vendor invoice document into the ledger.',
            'other': 'Anything else, including status checks, cancellations, disputes, amount-only questions, questions about vendors, or requests that do not plainly ask for one of the two actions now.'
        }
    }

    def normalize(prefix, chosen):
        if chosen == NONE:
            return NONE
        if chosen.startswith(prefix + '-'):
            return chosen
        return prefix + '-' + chosen

    def clean_value(value):
        if isinstance(value, float) and value == int(value):
            return int(value)
        return value

    def clean_record(record):
        cleaned = {}
        for key in record:
            cleaned[key] = clean_value(record[key])
        return cleaned

    def collect_candidates(pattern):
        candidates = []
        explicit = kit.find(pattern, request)
        numbers = kit.find(NUM_PATTERN, request)
        for item in explicit:
            if item not in candidates:
                candidates.append(item)
        for item in numbers:
            if item not in candidates:
                candidates.append(item)
        return candidates

    async def ask_choice(name, instructions, candidates):
        criteria = {}
        for candidate in candidates:
            criteria[candidate] = 'Use this candidate.'
        criteria[NONE] = 'None of the candidates fits.'
        result = await kit.ask({'request': request, 'candidates': candidates}, {name: {'type': 'choice', 'instructions': instructions, 'criteria': criteria}})
        return result[name]['choice']

    try:
        intent_result = await kit.ask({'request': request}, {'intent': action_question})
        intent = intent_result['intent']['choice']
    except Exception:
        return {'handoff': 'I could not judge the request safely.', 'read_only': True}

    if intent not in ACTIONS[:-1]:
        return {'handoff': 'The request is not a direct request to schedule a payment or enter a vendor invoice document now.', 'read_only': True}

    if intent == 'schedule_payment':
        candidates = collect_candidates(INV_PATTERN)
        if len(candidates) == 0:
            return {'handoff': 'I could not determine the invoice id to schedule payment for.', 'read_only': True}
        if len(candidates) == 1:
            invoice_id = normalize(INV_PREFIX, candidates[0])
        else:
            try:
                selected = await ask_choice('invoice_id', 'Choose the invoice id in the request that should be used for scheduling payment. If none of the candidates is the invoice to act on, choose none.', candidates)
            except Exception:
                return {'handoff': 'I could not determine the invoice id to schedule payment for.', 'read_only': True}
            invoice_id = normalize(INV_PREFIX, selected)
            if invoice_id == NONE:
                return {'handoff': 'I could not determine the invoice id to schedule payment for.', 'read_only': True}
        try:
            amount_result = await kit.procedure('amount_payable', invoice_id=invoice_id)
        except Exception:
            return {'handoff': 'The invoice could not be priced for payment, so I cannot schedule it.', 'read_only': True}
        if not isinstance(amount_result, dict) or 'error' in amount_result:
            return {'handoff': 'The invoice could not be priced for payment, so I cannot schedule it.', 'read_only': True}
        if 'amount_usd' not in amount_result or 'pay_on' not in amount_result:
            return {'handoff': 'The invoice could not be priced for payment, so I cannot schedule it.', 'read_only': True}
        amount_usd = clean_value(amount_result['amount_usd'])
        pay_on = amount_result['pay_on']
        try:
            schedule_result = await kit.procedure('schedule_payment', invoice_id=amount_result['invoice_id'], amount_usd=amount_usd, pay_on=pay_on)
        except Exception:
            return {'handoff': 'The payment could not be scheduled.', 'read_only': True}
        if not isinstance(schedule_result, dict) or 'error' in schedule_result:
            return {'handoff': 'The payment could not be scheduled.', 'read_only': True}
        return {'action': 'schedule_payment', 'arguments': {'invoice_id': amount_result['invoice_id'], 'amount_usd': amount_usd, 'pay_on': pay_on}, 'reply': 'Payment scheduled.'}

    if intent == 'record_invoice':
        candidates = collect_candidates(DOC_PATTERN)
        if len(candidates) == 0:
            return {'handoff': 'I could not determine the document id to enter into the ledger.', 'read_only': True}
        if len(candidates) == 1:
            doc_id = normalize(DOC_PREFIX, candidates[0])
        else:
            try:
                selected = await ask_choice('doc_id', 'Choose the document id in the request that should be used for entering the vendor invoice. If none of the candidates is the document to act on, choose none.', candidates)
            except Exception:
                return {'handoff': 'I could not determine the document id to enter into the ledger.', 'read_only': True}
            doc_id = normalize(DOC_PREFIX, selected)
            if doc_id == NONE:
                return {'handoff': 'I could not determine the document id to enter into the ledger.', 'read_only': True}
        try:
            parsed = await kit.procedure('parse_invoice', doc_id=doc_id)
        except Exception:
            return {'handoff': 'The document could not be parsed for ledger entry.', 'read_only': True}
        if not isinstance(parsed, dict) or 'error' in parsed:
            return {'handoff': 'The document could not be parsed for ledger entry.', 'read_only': True}
        cleaned = clean_record(parsed)
        try:
            record_result = await kit.procedure('record_invoice', **cleaned)
        except Exception:
            return {'handoff': 'The invoice could not be recorded in the ledger.', 'read_only': True}
        if not isinstance(record_result, dict) or 'error' in record_result:
            return {'handoff': 'The invoice could not be recorded in the ledger.', 'read_only': True}
        return {'action': 'record_invoice', 'arguments': cleaned, 'reply': 'Invoice recorded.'}

    return {'handoff': 'The request is outside the actions this program serves.', 'read_only': True}
"}

```python
"""Route with Jev so that requests which must not be acted on go read-only. Then move the busiest acting memories
from the language model to decision programs. A change is kept only if practice on the shared requests shows it
closes more of the gap with no new wrong action.

From A: the kinds prompt insists on a non-acting kind for look-alike requests. Failure feedback says whether each
request should have acted. Extraction is tolerant (JSON, fenced block, or a bare def).
From B: a program is judged inside the whole system (stored, then routed to) rather than in isolation. Comparison
ranks wrong actions first, then distance. The memory is restored when a candidate fails.
New: the writer calls left over are spent moving a second acting memory to a program.
"""

KINDS_PROMPT = """{contract}

Below are runs where the assistant, a language model, handled requests for
this job: each request, every tool call with its result, and the verdict.
Some requests are worded oddly, some should not be acted on at all, and
some runs went wrong.

List the kinds of request these runs show, and for each write what the
assistant should know the next time it meets one: how ids are really
written in the tools, which tools to call and in what order, and the
mistakes to avoid. Use as few kinds as cover the runs. Make sure there is a
kind (with "acts" false) for requests that look like the job but must not be
acted on: questions about status or amounts, refusals, holds, reversals,
edits, other changes the job does not cover, and requests outside the job.

Reply with only a JSON list. Each item has the keys "name" (short, in
snake_case), "description" (which requests belong to this kind, and which
similar ones don't), "guidance" (what the assistant should know), and
"acts" (true if a request of this kind should end in an action, false if
it should only be answered or passed on).

{episodes}"""

ROUTER = """async def decide(request, kit):
    found = await kit.recall(request, k=1)
    if len(found) == 0:
        return {"handoff": "nothing learned applies"}
    return {"serve": found[0]["name"]}
"""

ROUTER_PROMPT = """{contract}

You are writing the program that picks a memory for each request. It is
`async def decide(request, kit)`. It may call `await kit.recall(text, k)`,
which returns the closest memories as dicts with "name", "description",
"route" and "read_only", and it may ask Jev for typed judgments exactly as
the contract above describes. It returns {{"serve": name}} or hands off as
the contract says.

These are the memories:
{memories}

The key judgment: a memory that is not read-only lets the request be acted
on. Only send a request to such a memory when the request plainly asks for
that exact work to be done now. Some requests must NOT go to an acting memory:
- requests that only ask a question (status, whether something was done, who,
  which, how much, which account);
- requests that say not to do something, or to wait;
- requests that ask to undo, move, change, hold, delay, cancel, reject,
  delete or remind;
- requests that ask for any other work than what the memory covers.
Send each of these to a fitting read-only memory, or hand off read-only as the
contract says. Mentioning other ids that need nothing does not stop a request
from acting on its main id.

Do this: recall a few candidate memories; ask Jev, giving it the candidates
with their descriptions, which one fits and whether the request plainly asks
for that acting work to be done now. Serve an acting memory only when Jev says
yes. If unsure, prefer read-only. Never look for words or phrases in the
request text: every judgment about what the request asks for comes from Jev.
Code may only do exact things, such as reading memory fields.

Use only these builtins: Exception, KeyError, TypeError, ValueError, abs,
all, any, bool, dict, divmod, enumerate, filter, float, int, isinstance,
len, list, map, max, min, range, reversed, round, set, sorted, str, sum,
tuple, zip. No imports, no names starting with an underscore, no bare
except, no str.format.

{feedback}

Reply with only the Python source in one ```python block."""

PROGRAM_PROMPT = """{contract}

Write a decision program, `async def decide(request, kit)`, that serves
requests of one kind with no language model, following the contract above:
it calls tools and procedures, asks Jev for what code can't decide, and
returns an action or a hand-off as the contract says.

The kind:
name: {name}
description: {description}
what was learned about it:
{body}

Do the work exactly as the successful runs did, calling tools in the order
they show. Decide what the request means by asking Jev, never by looking for
words in the request. That covers which id it is about, even when the id is
written loosely, for example as a bare number. It also covers whether the
request plainly asks for this work now.

Use code only for what code knows exactly:
- normalizing an id Jev found to the form the tools use;
- calling tools;
- checking their results.

Before acting, check with the tools that the thing exists and is in the state
the work needs. Hand off read-only as the contract says, instead of acting,
in any of these cases:
- something doesn't fit;
- an id can't be found;
- a tool fails;
- the request asks for something other than this work.
A wrong action costs far more than a hand-off.

Use only these builtins: Exception, KeyError, TypeError, ValueError, abs,
all, any, bool, dict, divmod, enumerate, filter, float, int, isinstance,
len, list, map, max, min, range, reversed, round, set, sorted, str, sum,
tuple, zip. No imports, no names starting with an underscore, no bare
except, no str.format.

Runs of this job by the language model, with tool calls and verdicts:
{episodes}

{feedback}

Reply with only the Python source in one ```python block."""

ROUTER_ROUNDS = 2
PROGRAM_CALLS = 4
MAX_TARGETS = 2
MAX_IDS = 30


def extract(lab, reply):
    text = str(reply)
    source = None
    if "```" in text:
        parts = text.split("```")
        if len(parts) >= 3:
            lines = parts[1].split("\n")
            if len(lines) > 0 and "def " not in lines[0] and len(lines[0].strip()) < 20:
                lines = lines[1:]
            source = "\n".join(lines)
    if source is None or "async def decide" not in source:
        source = None
        try:
            value = lab.parse(text)
            if isinstance(value, dict) and "source" in value:
                source = str(value["source"])
        except Exception:
            source = None
    if source is None:
        at = text.find("async def decide")
        if at < 0:
            return None
        source = text[at:]
        fence = source.find("```")
        if fence >= 0:
            source = source[:fence]
    if "async def decide" not in source:
        return None
    return source.strip() + "\n"


def distance(reward):
    if reward is None:
        return 1.0
    if reward <= 0:
        return 3.0
    if reward <= 0.25:
        return 1.0
    if reward < 0.99:
        return 0.4
    return 0.0


async def evaluate(lab, source, ids, labels):
    total = 0.0
    served = {}
    bad = []
    wrong = 0
    for tid in ids:
        name = None
        reason = ""
        try:
            result = await lab.practice(source, tid)
            reward = result[0]
            reason = str(result[1])
            if len(result) > 2:
                name = result[2]
        except Exception as err:
            reward = 0.25
            reason = "program failed: " + str(err)
        d = distance(reward)
        total += d
        if d >= 3:
            wrong += 1
        key = str(name)
        if key not in served:
            served[key] = []
        served[key].append(d)
        if d >= 0.4:
            should = labels.get(tid)
            tag = "unknown"
            if should is True:
                tag = "should act"
            if should is False:
                tag = "should NOT act"
            try:
                text = lab.request(tid)
            except Exception:
                text = str(tid)
            bad.append((d, "- [" + tag + "] " + str(text) + " -> memory " + key + ": " + reason))
    bad = sorted(bad, key=lambda pair: -pair[0])
    return {"total": total, "served": served, "bad": [b[1] for b in bad], "wrong": wrong}


def feedback_text(result):
    if result is None or len(result["bad"]) == 0:
        return ""
    return "A previous attempt got these requests wrong or only partly right; fix them:\n" + "\n".join(result["bad"][:20])


def better(a, b):
    if a["wrong"] != b["wrong"]:
        return a["wrong"] < b["wrong"]
    return a["total"] < b["total"]


def describe_memories(mems):
    lines = []
    for name in mems:
        m = mems[name]
        lines.append("- " + name + " (route " + str(m.get("route", "none")) + ", read_only "
                     + str(bool(m.get("read_only", False))) + "): " + str(m.get("description", "")))
    return "\n".join(lines)


def pick_targets(mems, best):
    scored = []
    for name in best["served"]:
        if name not in mems:
            continue
        m = mems[name]
        if m.get("read_only", False) or m.get("route") == "program":
            continue
        n = len([d for d in best["served"][name] if d == 0.4])
        if n > 0:
            scored.append((n, name))
    scored = sorted(scored, key=lambda pair: -pair[0])
    return [pair[1] for pair in scored[:MAX_TARGETS]]


async def learn(lab):
    shown = "\n\n".join(lab.render(e) for e in lab.episodes)
    mems = {}
    if len(lab.memories) > 0:
        for memory in lab.memories:
            mems[memory["name"]] = dict(memory)
    else:
        reply = await lab.ask(lab.fill(KINDS_PROMPT, contract=lab.contract, episodes=shown))
        kinds = []
        try:
            kinds = lab.parse(reply)
        except Exception as err:
            lab.note("kinds parse failed: " + str(err))
        if not isinstance(kinds, list):
            kinds = []
        for kind in kinds:
            try:
                mems[str(kind["name"])] = {"name": str(kind["name"]), "description": str(kind["description"]),
                                           "body": str(kind["guidance"]), "route": "none",
                                           "read_only": not bool(kind["acts"])}
            except (KeyError, TypeError) as err:
                lab.note("skipped a kind: " + str(err))
    for name in mems:
        lab.remember(**mems[name])

    labels = {}
    ids = []
    for test in lab.tests:
        labels[test["id"]] = test["should_act"]
        ids.append(test["id"])
    if len(ids) == 0:
        ids = list(lab.stream())
    ids = ids[:MAX_IDS]

    router = ROUTER
    best = await evaluate(lab, ROUTER, ids, labels)
    feedback = feedback_text(best)
    for attempt in range(ROUTER_ROUNDS):
        try:
            reply = await lab.ask(lab.fill(ROUTER_PROMPT, contract=lab.contract,
                                           memories=describe_memories(mems), feedback=feedback))
            source = extract(lab, reply)
            if source is None:
                continue
            result = await evaluate(lab, source, ids, labels)
        except Exception as err:
            lab.note("router attempt failed: " + str(err))
            continue
        if better(result, best):
            best = result
            router = source
            feedback = feedback_text(result)
            if result["total"] == 0:
                break
        else:
            feedback = feedback_text(result)
    lab.note("router distance " + str(best["total"]) + " wrong " + str(best["wrong"]))

    calls = PROGRAM_CALLS
    for target in pick_targets(mems, best):
        if calls <= 0:
            break
        original = dict(mems[target])
        feedback = ""
        kept = False
        tries = 2
        while tries > 0 and calls > 0:
            tries -= 1
            calls -= 1
            try:
                reply = await lab.ask(lab.fill(PROGRAM_PROMPT, contract=lab.contract, name=target,
                                               description=str(original.get("description", "")),
                                               body=str(original.get("body", "")),
                                               episodes=shown, feedback=feedback))
                program = extract(lab, reply)
                if program is None:
                    continue
                candidate = dict(original)
                candidate["body"] = program
                candidate["route"] = "program"
                candidate["read_only"] = False
                lab.remember(**candidate)
                result = await evaluate(lab, router, ids, labels)
            except Exception as err:
                lab.note("program attempt failed: " + str(err))
                lab.remember(**mems[target])
                continue
            if better(result, best) and result["wrong"] <= best["wrong"]:
                best = result
                mems[target] = candidate
                kept = True
                lab.note("moved " + target + " to a program; distance " + str(result["total"]))
                if len([d for d in result["served"].get(target, []) if d > 0]) == 0:
                    break
            else:
                lab.remember(**mems[target])
            feedback = feedback_text(result)
        if not kept:
            lab.remember(**original)
    return router
